// 该函数计算输入数据的CRC校验值。
// cp：输入数据的指针（数据缓冲区）。
// len：数据的长度。
uint16_t calculateCRC16(uint8_t *cp, uint16_t len)
{
    uint16_t fcs = 0xFFFF;

    while (len--)
    {
        fcs = (uint16_t)((fcs >> 8) ^ crc16Table [(fcs ^ *cp++) & 0xff]);
    }

    return (fcs ^ 0xFFFF);
}
